import {validateV3Bundle,validateV4Bundle,migrateAnyToV4,migrateV2ToV3} from './migration.js';
const clone=value=>structuredClone(value),merge=(a,b)=>[...new Map([...a,...b].map(item=>[item.id,clone(item)])).values()];
export function exportV4Bundle(state){return{schemaVersion:4,application:'LMN Knowledge System',exportedAt:new Date().toISOString(),knowledge:clone(state.knowledge??[]),relations:clone(state.relations??[]),representations:clone(state.representations??[]),structureTemplates:clone(state.structureTemplates??[]),structureInstances:clone(state.structureInstances??[])}}
export function importV4Bundle(data,current){const incoming=migrateAnyToV4(data),validation=validateV4Bundle(incoming);if(!validation.valid)return{...validation,state:current};const state={...current};for(const key of['knowledge','relations','representations','structureTemplates','structureInstances'])state[key]=merge(current[key]??[],incoming[key]??[]);return{valid:true,errors:[],state}}
export function exportV3Bundle(state){return{...exportV4Bundle(state),schemaVersion:3}}
export function importV3Bundle(data,current){if((data.schemaVersion??data.schema_version)===4)return importV4Bundle(data,current);const incoming=(data.schemaVersion??data.schema_version)===3?data:migrateV2ToV3(data),validation=validateV3Bundle(incoming);if(!validation.valid)return{...validation,state:current};const state={...current};for(const key of['knowledge','relations','representations','structureTemplates','structureInstances'])state[key]=merge(current[key]??[],incoming[key]??[]);return{valid:true,errors:[],state}}
